import{c as e,Q as s,j as t,m as n}from"./chunks/framework.DxgWTcNC.js";const u=JSON.parse('{"title":"Installing radare2 and the Ecosystem","description":"","frontmatter":{},"headers":[],"relativePath":"part1/02-install.md","filePath":"part1/02-install.md","lastUpdated":null}'),i={name:"part1/02-install.md"};function o(p,a,r,d,c,l){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="installing-radare2-and-the-ecosystem" tabindex="-1">Installing radare2 and the Ecosystem <a class="header-anchor" href="#installing-radare2-and-the-ecosystem" aria-label="Permalink to &quot;Installing radare2 and the Ecosystem&quot;">​</a></h1><p>This chapter gets you to a working installation that includes the things the rest of the book assumes you have: radare2 itself, the package manager <code>r2pm</code>, the two decompilers (<code>r2ghidra</code> and <code>r2dec</code>), and a handful of plugins that come up in the architecture chapters.</p><h2 id="installing-radare2" tabindex="-1">Installing radare2 <a class="header-anchor" href="#installing-radare2" aria-label="Permalink to &quot;Installing radare2&quot;">​</a></h2><p>Radare2 changes fast — the master branch typically has features and bug fixes that are months ahead of distribution packages. For serious work, <strong>build from git</strong>. It is a five-minute install on any Unix.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ git clone https://github.com/radareorg/radare2</span></span>
<span class="line"><span>$ cd radare2</span></span>
<span class="line"><span>$ sys/install.sh</span></span></code></pre></div><p><code>sys/install.sh</code> builds with the project&#39;s own bootstrap script (<code>acr</code>), installs to <code>/usr/local</code>, and avoids most of the autotools traps. On macOS it works under Homebrew&#39;s prefix or system prefix; on Linux it needs <code>gcc</code>, <code>make</code>, <code>pkg-config</code>, and <code>git</code>. No other dependencies are required for the core.</p><p>To upgrade, pull and run <code>sys/install.sh</code> again. The script handles incremental rebuilds.</p><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>Use <code>sys/user.sh</code> instead of <code>sys/install.sh</code> if you do not want to install to a system prefix. It puts r2 under <code>~/.local</code>. Add <code>~/.local/bin</code> to <code>PATH</code> and you are done — no <code>sudo</code> involved.</p></div><p>Verify the install:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ r2 -v</span></span>
<span class="line"><span>radare2 6.1.4 +0 abi:83 @ darwin-arm_64 ...</span></span></code></pre></div><p>If you do prefer your distribution&#39;s package, <code>apt install radare2</code>, <code>brew install radare2</code>, <code>pacman -S radare2</code>, and friends all work. They will be one or two minor versions behind. For everything in this book that is fine; for chasing a specific bug fix it is not.</p><h2 id="the-r2pm-package-manager" tabindex="-1">The r2pm package manager <a class="header-anchor" href="#the-r2pm-package-manager" aria-label="Permalink to &quot;The r2pm package manager&quot;">​</a></h2><p><code>r2pm</code> is radare2&#39;s plugin and tool manager. It builds plugins from source against your installed r2, drops them in the right place, and keeps them in sync as you upgrade.</p><p>Initialise the database:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ r2pm -U</span></span></code></pre></div><p><code>-U</code> updates the package index. You will need to run it occasionally to pick up new plugins.</p><p>List installed packages:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ r2pm -l</span></span></code></pre></div><p>Search:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ r2pm -s ghidra</span></span></code></pre></div><p>Install:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ r2pm -ci r2ghidra</span></span>
<span class="line"><span>$ r2pm -ci r2dec</span></span></code></pre></div><p>The <code>-c</code> flag tells r2pm to clean the build directory before building. Use it if a previous build is stale.</p><p>Uninstall:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ r2pm -u r2dec</span></span></code></pre></div><h2 id="installing-the-decompilers" tabindex="-1">Installing the decompilers <a class="header-anchor" href="#installing-the-decompilers" aria-label="Permalink to &quot;Installing the decompilers&quot;">​</a></h2><p>Two decompilers cover most of the work in this book.</p><p><strong>r2ghidra</strong> is a port of Ghidra&#39;s decompiler engine that runs entirely inside r2. The decompiler binary is C++; r2ghidra wraps it as a native r2 plugin. Output quality matches standalone Ghidra for the vast majority of functions. It is the decompiler you will use 90% of the time.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ r2pm -ci r2ghidra</span></span></code></pre></div><p>The first build takes a few minutes. After it finishes, the <code>pdg</code> command inside r2 produces decompiled C output for the function under the cursor.</p><p><strong>r2dec</strong> is a JavaScript-based decompiler that ships as a duktape script. It is much faster to start up than r2ghidra (no C++ engine to load) and produces shorter, less precise output. It is good for &quot;what does this function look like, roughly&quot; before you commit to running r2ghidra. It is also useful in scripts where you want decompilation as a string and do not want the r2ghidra startup cost.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ r2pm -ci r2dec</span></span></code></pre></div><p>The r2dec command is <code>pdd</code>.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>If both are installed, <code>pdg</code> invokes r2ghidra and <code>pdd</code> invokes r2dec. You can have both installed simultaneously — they do not conflict.</p></div><h2 id="architecture-specific-plugins" tabindex="-1">Architecture-specific plugins <a class="header-anchor" href="#architecture-specific-plugins" aria-label="Permalink to &quot;Architecture-specific plugins&quot;">​</a></h2><p>Most architectures the book covers are built into core r2. Two are worth installing as plugins because they are commonly missing or under-supported by default builds.</p><p><strong>Xtensa via the V850/Xtensa plugin set.</strong> Modern r2 (5.x) ships with Xtensa support that handles ESP32 (LX6) and ESP32-S2/S3 (LX7) including windowed register decoding. Confirm with <code>e asm.arch=?</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>[0x00000000]&gt; e asm.arch=?</span></span>
<span class="line"><span>arc arm avr ...</span></span>
<span class="line"><span>... xtensa ...</span></span></code></pre></div><p>If <code>xtensa</code> is missing, you have an unusually stripped build; rebuild from git source.</p><p><strong>8051.</strong> First-class. Listed as <code>8051</code> in <code>asm.arch</code>.</p><p><strong>ESP image format.</strong> Add support for <code>.bin</code> ESP firmware images:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ r2pm -ci esilsolve  # not strictly an arch plugin but useful for ESIL work</span></span></code></pre></div><p>For loading raw ESP images, you typically use <code>esptool.py</code> to extract the sections first, then load them with <code>r2 -m</code>. Chapter 14 covers this.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Radare2 reads <code>~/.radare2rc</code> (Linux/macOS) or <code>%APPDATA%/radare2/radare2rc</code> (Windows) on startup. A reasonable starter config:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span># ~/.radare2rc</span></span>
<span class="line"><span>e scr.utf8=true              # use UTF-8 box-drawing in graphs</span></span>
<span class="line"><span>e scr.color=3                # 256-colour output</span></span>
<span class="line"><span>e asm.cmt.right=true         # comments on the right of disassembly</span></span>
<span class="line"><span>e asm.cmt.col=60             # comment column</span></span>
<span class="line"><span>e asm.bytes=false            # hide raw bytes (cleaner output)</span></span>
<span class="line"><span>e asm.lines.width=14         # width of branch arrows</span></span>
<span class="line"><span>e asm.flags.middle=2         # show flags inline at function entry</span></span>
<span class="line"><span>e dbg.bep=loader             # break at loader entry, not main</span></span>
<span class="line"><span>e search.in=raw              # /-search the whole file by default</span></span>
<span class="line"><span>e cfg.fortunes=false         # disable startup fortune cookie</span></span></code></pre></div><p>Per-project settings go in <code>~/.config/radare2/projects/&lt;project&gt;/rc</code>. Both files are sourced; per-project wins.</p><h2 id="sanity-check" tabindex="-1">Sanity check <a class="header-anchor" href="#sanity-check" aria-label="Permalink to &quot;Sanity check&quot;">​</a></h2><p>Open a binary you have lying around — anything: an ELF, a Mach-O, an old firmware blob — and verify the basics:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ r2 /bin/ls</span></span>
<span class="line"><span>[0x100003a40]&gt; aaa</span></span>
<span class="line"><span>[0x100003a40]&gt; afl | head</span></span>
<span class="line"><span>0x100003a40    1 21           sym.entry</span></span>
<span class="line"><span>0x100003a55   13 1057 -&gt; 1029 entry0</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>[0x100003a40]&gt; pdf @ entry0 | head -20</span></span></code></pre></div><p>If you see disassembly, you are done. If <code>pdf</code> produces nothing, you have a binary radare2 cannot analyse and that is a separate adventure (Chapter 14).</p><h2 id="optional-iaito-or-cutter-for-a-gui" tabindex="-1">Optional: Iaito or Cutter for a GUI <a class="header-anchor" href="#optional-iaito-or-cutter-for-a-gui" aria-label="Permalink to &quot;Optional: Iaito or Cutter for a GUI&quot;">​</a></h2><p>The book is written around the command-line UI because that is what scales to scripting and remote debugging. If you want a graphical front-end for some of the work, install <strong>Iaito</strong> (the radare2 project&#39;s official Qt front-end) or <strong>Cutter</strong> (a community fork that has diverged somewhat). Both wrap r2 underneath, so commands you learn here work in their console panel.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>$ r2pm -ci iaito</span></span></code></pre></div><p>Cutter is distributed as an AppImage on Linux and as a notarised .app on macOS — see its GitHub releases page.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>Cutter and Iaito periodically diverge from r2&#39;s command set. If a command in this book does not work in their console panel, run it in plain <code>r2</code> first to confirm it works, then file a bug against the GUI.</p></div>`,56)])])}const g=e(i,[["render",o]]);export{u as __pageData,g as default};
